package org.sleepwell.app;
import android.content.Context;import android.os.*;import android.speech.tts.*;import java.lang.ref.WeakReference;import java.util.*;
/** Silent, explicit inventory refresh. No speak, synthesis-to-file, language install or download action. */
final class NarrationVoiceDiscovery implements AutoCloseable {
 interface Observer{void changed();}final Context app;final Handler main=new Handler(Looper.getMainLooper());final HandlerThread thread=new HandlerThread("offline-voice-inventory");final Handler worker;private WeakReference<Observer> observer=new WeakReference<>(null);private volatile int generation;private volatile boolean closed;private NarrationVoiceEngine engine;private Runnable timeout;List<NarrationVoiceEngine.Installed> installed=List.of();List<NarrationVoice> voices=List.of();String requested="",message="Choose an installed engine, then Refresh voices. Nothing will play.";boolean busy;
 NarrationVoiceDiscovery(Context context){app=context.getApplicationContext();thread.start();worker=new Handler(thread.getLooper());inventory();}
 void observe(Observer target){observer=new WeakReference<>(target);target.changed();}void detach(Observer target){if(observer.get()==target)observer.clear();}private void publish(){if(closed)return;Observer target=observer.get();if(target!=null)target.changed();}private boolean live(int ticket){return !closed&&generation==ticket;}
 void inventory(){worker.post(()->{try{List<NarrationVoiceEngine.Installed> found=NarrationVoiceEngine.installed(app);if(found.size()>30)throw new IllegalStateException("Too many speech engines are installed for this chooser.");main.post(()->{if(closed)return;installed=found;if(found.isEmpty())message="No installed speech engines are visible. Auto can be saved, but narration needs an offline English voice installed in Android settings.";publish();});}catch(RuntimeException unavailable){main.post(()->{if(closed)return;message="Installed engines are unavailable or access is denied. Refresh after reviewing Android text-to-speech settings.";publish();});}});}
 void refresh(String requested){if(closed||busy)return;int ticket=++generation;this.requested=requested;voices=List.of();busy=true;message="Querying installed offline English voices…";publish();worker.post(()->{if(!live(ticket))return;try{release();List<NarrationVoiceEngine.Installed> fresh=NarrationVoiceEngine.installed(app);if(fresh.size()>30)throw new IllegalStateException("Too many installed speech engines for this chooser.");main.post(()->{if(live(ticket)){installed=fresh;publish();}});engine=new NarrationVoiceEngine(app,requested,result->worker.post(()->initialized(ticket,result)));timeout=()->{if(live(ticket))finish(ticket,List.of(),"Voice discovery timed out. Press Refresh to retry.");};worker.postDelayed(timeout,10000);}catch(RuntimeException failure){finish(ticket,List.of(),failure.getMessage()==null?"The requested engine is unavailable.":failure.getMessage());}});}
 private void initialized(int ticket,int result){if(!live(ticket)||engine==null)return;try{if(result!=TextToSpeech.SUCCESS||engine==null||engine.speech==null)throw new IllegalStateException("The requested engine did not initialize. Choose another engine or Auto.");engine.checkRequested();List<NarrationVoice> choices=new ArrayList<>();Set<Voice> declared=engine.speech.getVoices();if(declared!=null){if(declared.size()>500)throw new IllegalStateException("This engine declares too many voices. Choose another engine or Auto.");for(Voice voice:declared)if(NarrationVoice.offline(voice)&&engine.speech.isLanguageAvailable(voice.getLocale())>=TextToSpeech.LANG_AVAILABLE)choices.add(NarrationVoice.of(requested,voice));}choices.sort(Comparator.comparing((NarrationVoice v)->v.locale).thenComparing(v->v.name));finish(ticket,choices,choices.isEmpty()?"No installed offline English voices were declared by this request. Install English offline data in Android settings, then Refresh. No download is started here.":choices.size()+" installed offline English voices declared. Choose one, then Save.");}catch(RuntimeException failure){finish(ticket,List.of(),failure.getMessage()==null?"Offline voice discovery failed.":failure.getMessage());}}
 private void finish(int ticket,List<NarrationVoice> found,String status){if(!live(ticket))return;if(timeout!=null)worker.removeCallbacks(timeout);try{release();}catch(RuntimeException cleanup){found=List.of();status=cleanup.getMessage();}final List<NarrationVoice> result=List.copyOf(found);final String message=status;main.post(()->{if(!live(ticket))return;voices=result;busy=false;this.message=message;publish();});}
 private void release(){NarrationVoiceEngine owned=engine;engine=null;if(owned!=null)owned.close();}
 void cancel(){if(closed)return;generation++;busy=false;voices=List.of();message="Voice query stopped. Press Refresh to verify a selection again.";worker.post(()->{try{release();}catch(RuntimeException failure){main.post(()->{if(!closed){message=failure.getMessage();publish();}});}});publish();}
 boolean verified(NarrationVoice voice){if(voice.automatic())return true;if(busy||!requested.equals(voice.engine))return false;for(NarrationVoice found:voices)if(found.name.equals(voice.name)&&found.locale.equals(voice.locale)&&found.engine.equals(voice.engine))return true;return false;}
 public void close(){if(closed)return;closed=true;generation++;observer.clear();worker.post(()->{try{release();}finally{thread.quitSafely();}});}
}
